cd /tmp; firecrawl interact -s 01a14b55-be33-71b9-93b8-7d1944887e46 --node --timeout 200 -c '
const out=[];
for (const dz of ["10001","60601","33101","98101","96813"]) for (const p of [2,6]) {
  const u=`https://postcalc.usps.com/Calculator/MailServices?country=0&ccode=US&oz=94107&omil=False&dz=${dz}&dmil=False&retail=False&mdt=10%2F17%2F2026&mdz=15%3A29&m=7&hscode=False&p=${p}&o=0&rect=True&l=12&h=4&w=9&g=0`;
  await page.goto(u,{waitUntil:"domcontentloaded"});
  await page.waitForTimeout(1500);
  const t=await page.innerText("body");
  const hdr=(t.match(/Large Package.*\n.*\n?/)||t.match(/weight.*\n.*/)||[""])[0].replace(/\n/g," ");
  const sec=n=>{const i=t.indexOf(n+"\n");if(i<0)return "n/a";const s=t.slice(i,i+400).split("\n");const l=s.find(x=>/Normal Delivery/.test(x));return l||s.slice(0,6).join("|")};
  out.push(`${dz} ${p}lb | ${hdr}\n  PM: ${sec("Priority Mail®")}\n  GA: ${sec("USPS Ground Advantage®")}`);
}
console.log(out.join("\n"));
' 2>&1 | tail -50

